package auth

import (
	"context"
	"errors"
	"log/slog"
	"strings"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/peer"
	"google.golang.org/grpc/status"
)

const (
	MetadataAuthorizationKey = "authorization"
	TokenPrefix              = "Bearer "
)

var (
	ErrMetadataFetchFailed = errors.New("metadata fetch failed")
)

type GrpcAuthenticationDelegator struct {
	provider AuthenticationProvider

	validate func(ctx context.Context, provider AuthenticationProvider) (string, error)
}

func (delegator *GrpcAuthenticationDelegator) GetUnaryInterceptor() grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req any, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (any, error) {
		_, err := delegator.validate(ctx, delegator.provider)
		if err != nil {
			return nil, status.Error(codes.Unauthenticated, err.Error())
		}
		// todo: set username to metadata to support authorization
		return handler(ctx, req)
	}
}

func (delegator *GrpcAuthenticationDelegator) GetStreamInterceptor() grpc.StreamServerInterceptor {
	return func(srv any, ss grpc.ServerStream, _ *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
		_, err := delegator.validate(ss.Context(), delegator.provider)
		if err != nil {
			return status.Error(codes.Unauthenticated, err.Error())
		}
		// todo: set username to metadata to support authorization
		return handler(srv, ss)
	}
}

func NewGrpcAuthenticationDelegator(provider AuthenticationProvider) (*GrpcAuthenticationDelegator, error) {
	delegator := &GrpcAuthenticationDelegator{
		provider: provider,
	}
	switch provider.AcceptParamType() {
	case ProviderParamTypeToken:
		delegator.validate = validateTokenWithContext
	default:
		return nil, ErrUnMatchedAuthenticationParamType
	}
	return delegator, nil
}

func validateTokenWithContext(ctx context.Context, provider AuthenticationProvider) (string, error) {
	meta, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return "", ErrMetadataFetchFailed
	}
	peerMeta, ok := peer.FromContext(ctx)
	if !ok {
		return "", ErrMetadataFetchFailed
	}
	val := meta.Get(MetadataAuthorizationKey)
	if len(val) < 1 {
		slog.Debug("Receive empty token from the client",
			slog.String("peer", peerMeta.Addr.String()))
		return "", ErrEmptyToken
	}
	token := strings.TrimPrefix(val[0], TokenPrefix)
	var userName string
	var err error
	if userName, err = provider.Authenticate(ctx, token); err != nil {
		slog.Debug("Failed to authenticate token",
			slog.String("peer", peerMeta.Addr.String()),
			slog.String("token", token))
		return "", err
	}
	return userName, nil
}

package cassandradb

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"time"

	"github.com/gocql/gocql"
	"github.com/google/uuid"

	"github.com/authorizerdev/authorizer/internal/storage/schemas"
)

func (p *provider) AddAuthenticator(ctx context.Context, authenticators *schemas.Authenticator) (*schemas.Authenticator, error) {
	exists, _ := p.GetAuthenticatorDetailsByUserId(ctx, authenticators.UserID, authenticators.Method)
	if exists != nil {
		return authenticators, nil
	}

	if authenticators.ID == "" {
		authenticators.ID = uuid.New().String()
	}

	authenticators.CreatedAt = time.Now().Unix()
	authenticators.UpdatedAt = time.Now().Unix()

	bytes, err := json.Marshal(authenticators)
	if err != nil {
		return nil, err
	}

	// use decoder instead of json.Unmarshall, because it converts int64 -> float64 after unmarshalling
	decoder := json.NewDecoder(strings.NewReader(string(bytes)))
	decoder.UseNumber()
	authenticatorsMap := map[string]interface{}{}
	err = decoder.Decode(&authenticatorsMap)
	if err != nil {
		return nil, err
	}

	fields := "("
	values := "("
	for key, value := range authenticatorsMap {
		if value != nil {
			if key == "_id" {
				fields += "id,"
			} else {
				fields += key + ","
			}

			valueType := reflect.TypeOf(value)
			if valueType.Name() == "string" {
				values += fmt.Sprintf("'%s',", value.(string))
			} else {
				values += fmt.Sprintf("%v,", value)
			}
		}
	}

	fields = fields[:len(fields)-1] + ")"
	values = values[:len(values)-1] + ")"

	query := fmt.Sprintf("INSERT INTO %s %s VALUES %s IF NOT EXISTS", KeySpace+"."+schemas.Collections.Authenticators, fields, values)
	err = p.db.Query(query).Exec()
	if err != nil {
		return nil, err
	}

	return authenticators, nil
}

func (p *provider) UpdateAuthenticator(ctx context.Context, authenticators *schemas.Authenticator) (*schemas.Authenticator, error) {
	authenticators.UpdatedAt = time.Now().Unix()

	bytes, err := json.Marshal(authenticators)
	if err != nil {
		return nil, err
	}
	// use decoder instead of json.Unmarshall, because it converts int64 -> float64 after unmarshalling
	decoder := json.NewDecoder(strings.NewReader(string(bytes)))
	decoder.UseNumber()
	authenticatorsMap := map[string]interface{}{}
	err = decoder.Decode(&authenticatorsMap)
	if err != nil {
		return nil, err
	}

	updateFields := ""
	for key, value := range authenticatorsMap {
		if key == "_id" {
			continue
		}

		if key == "_key" {
			continue
		}

		if value == nil {
			updateFields += fmt.Sprintf("%s = null, ", key)
			continue
		}

		valueType := reflect.TypeOf(value)
		if valueType.Name() == "string" {
			updateFields += fmt.Sprintf("%s = '%s', ", key, value.(string))
		} else {
			updateFields += fmt.Sprintf("%s = %v, ", key, value)
		}
	}
	updateFields = strings.Trim(updateFields, " ")
	updateFields = strings.TrimSuffix(updateFields, ",")

	query := fmt.Sprintf("UPDATE %s SET %s WHERE id = '%s'", KeySpace+"."+schemas.Collections.Authenticators, updateFields, authenticators.ID)
	err = p.db.Query(query).Exec()
	if err != nil {
		return nil, err
	}

	return authenticators, nil
}

func (p *provider) GetAuthenticatorDetailsByUserId(ctx context.Context, userId string, authenticatorType string) (*schemas.Authenticator, error) {
	var authenticators schemas.Authenticator
	query := fmt.Sprintf("SELECT id, user_id, method, secret, recovery_codes, verified_at, created_at, updated_at FROM %s WHERE user_id = '%s' AND method = '%s' LIMIT 1 ALLOW FILTERING", KeySpace+"."+schemas.Collections.Authenticators, userId, authenticatorType)
	err := p.db.Query(query).Consistency(gocql.One).Scan(&authenticators.ID, &authenticators.UserID, &authenticators.Method, &authenticators.Secret, &authenticators.RecoveryCodes, &authenticators.VerifiedAt, &authenticators.CreatedAt, &authenticators.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &authenticators, nil
}

import { GraphQLError } from 'graphql';
import logger from '../../logger';

function calculateQueryComplexity(operation, fragments) {
  let maxDepth = 0;
  let totalFields = 0;

  function visitSelectionSet(selectionSet, depth, visitedFragments) {
    if (!selectionSet) {
      return;
    }
    for (const selection of selectionSet.selections) {
      if (selection.kind === 'Field') {
        totalFields++;
        const newDepth = depth + 1;
        if (newDepth > maxDepth) {
          maxDepth = newDepth;
        }
        if (selection.selectionSet) {
          visitSelectionSet(selection.selectionSet, newDepth, visitedFragments);
        }
      } else if (selection.kind === 'InlineFragment') {
        visitSelectionSet(selection.selectionSet, depth, visitedFragments);
      } else if (selection.kind === 'FragmentSpread') {
        const name = selection.name.value;
        if (visitedFragments.has(name)) {
          continue;
        }
        const fragment = fragments[name];
        if (fragment) {
          const branchVisited = new Set(visitedFragments);
          branchVisited.add(name);
          visitSelectionSet(fragment.selectionSet, depth, branchVisited);
        }
      }
    }
  }

  visitSelectionSet(operation.selectionSet, 0, new Set());

  return { depth: maxDepth, fields: totalFields };
}

function createComplexityValidationPlugin(getConfig) {
  return {
    requestDidStart: (requestContext) => ({
      didResolveOperation: async () => {
        const auth = requestContext.contextValue?.auth;
        if (auth?.isMaster || auth?.isMaintenance) {
          return;
        }

        const config = getConfig();
        if (!config) {
          return;
        }

        const { graphQLDepth, graphQLFields } = config;
        if (graphQLDepth === -1 && graphQLFields === -1) {
          return;
        }

        const fragments = {};
        for (const definition of requestContext.document.definitions) {
          if (definition.kind === 'FragmentDefinition') {
            fragments[definition.name.value] = definition;
          }
        }

        const { depth, fields } = calculateQueryComplexity(
          requestContext.operation,
          fragments
        );

        if (graphQLDepth !== -1 && depth > graphQLDepth) {
          const message = `GraphQL query depth of ${depth} exceeds maximum allowed depth of ${graphQLDepth}`;
          logger.warn(message);
          throw new GraphQLError(message, {
            extensions: {
              http: { status: 400 },
            },
          });
        }

        if (graphQLFields !== -1 && fields > graphQLFields) {
          const message = `Number of GraphQL fields (${fields}) exceeds maximum allowed (${graphQLFields})`;
          logger.warn(message);
          throw new GraphQLError(message, {
            extensions: {
              http: { status: 400 },
            },
          });
        }
      },
    }),
  };
}

