    output: string
    updatedDate: Date
    sequenceNo: number
}

export enum EvaluationStatus {
    PENDING = 'pending',
    COMPLETED = 'completed',
    ERROR = 'error'
}

export interface IEvaluation {
    id: string
    name: string
    chatflowId: string
    chatflowName: string
    datasetId: string
    datasetName: string
    evaluationType: string
    additionalConfig: string //json
    average_metrics: string //json
    status: string
    runDate: Date
