    protected async selectChat(sessionId?: string): Promise<void> {
        let activeSessionId = sessionId;

        if (!activeSessionId) {
            const item = await this.askForChatSession();
            if (item === undefined) {
                return;
            }
            activeSessionId = item.id;
        }

        this.chatService.setActiveSession(activeSessionId!, { focus: true });
    }

    protected async askForChatSession(): Promise<QuickPickItem | undefined> {
        const getItems = async (): Promise<QuickPickItem[]> => {
            const activeSessions = this.chatService.getSessions()
                .filter(session => session.title)
                .map(session => ({
                    session,
                    isActive: true,
                    lastDate: session.lastInteraction ? session.lastInteraction.getTime() : 0
                }));

            // Try to load persisted sessions, but don't fail if it doesn't work
            let persistedSessions: Array<{ metadata: { sessionId: string; title: string; saveDate: number }; isActive: false; lastDate: number }> = [];
            try {
                const persistedIndex = await this.chatService.getPersistedSessions();
                const activeIds = new Set(activeSessions.map(s => s.session.id));
                persistedSessions = Object.values(persistedIndex)
                    .filter(metadata => !activeIds.has(metadata.sessionId))
                    .map(metadata => ({
                        metadata,
                        isActive: false,
                        lastDate: metadata.saveDate
                    }));
            } catch (error) {
                this.logger.error('Failed to load persisted sessions, showing only active sessions', error);
                // Continue with just active sessions
            }

            // Combine and sort by last interaction/message date
            const allSessions = [
                ...activeSessions.map(s => ({
                    isActive: true,
                    id: s.session.id,
                    title: s.session.title!,
                    lastDate: s.lastDate,
                    firstRequestText: s.session.model.getRequests().at(0)?.request.text
                })),
                ...persistedSessions.map(s => ({
                    isActive: false,
                    id: s.metadata.sessionId,
                    title: s.metadata.title,
                    lastDate: s.lastDate,
                    firstRequestText: undefined
                }))
            ].sort((a, b) => b.lastDate - a.lastDate);

            return allSessions.map(session => {
                // Add icon for persisted sessions to visually distinguish them
                const icon = session.isActive ? '' : '$(archive) ';
                const label = `${icon}${session.title}`;

                return <QuickPickItem>({
                    label,
                    description: formatTimeAgo(session.lastDate, false),
                    detail: session.firstRequestText || (session.isActive ? undefined : nls.localize('theia/ai/chat-ui/persistedSession', 'Persisted session (click to restore)')),
                    id: session.id,
                    buttons: [AIChatContribution.RENAME_CHAT_BUTTON, AIChatContribution.REMOVE_CHAT_BUTTON]
                });
            });
        };

        const defer = new Deferred<QuickPickItem | undefined>();
        const quickPick = this.quickInputService.createQuickPick();
        quickPick.placeholder = nls.localize('theia/ai/chat-ui/selectChat', 'Select chat');
        quickPick.canSelectMany = false;
        quickPick.busy = true;
        quickPick.show();

        // Load items asynchronously
        getItems().then(items => {
            quickPick.items = items;
            quickPick.busy = false;
        }).catch(error => {
            this.logger.error('Failed to load chat sessions', error);
            quickPick.busy = false;
            quickPick.placeholder = nls.localize('theia/ai/chat-ui/failedToLoadChats', 'Failed to load chat sessions');
        });

        quickPick.onDidTriggerItemButton(async context => {
            if (context.button === AIChatContribution.RENAME_CHAT_BUTTON) {
                quickPick.hide();
                await this.renameSession(context.item.id!);
            } else if (context.button === AIChatContribution.REMOVE_CHAT_BUTTON) {
                await this.deleteSession(context.item.id!);
                const items = await getItems();
                quickPick.items = items;
                if (items.length === 0) {
                    quickPick.hide();
                }
            }
        });

        quickPick.onDidAccept(async () => {
            const selectedItem = quickPick.selectedItems[0];
            if (selectedItem) {
                // Restore session if not already loaded
                const session = this.chatService.getSession(selectedItem.id!);
                if (!session) {
                    try {
                        await this.chatService.getOrRestoreSession(selectedItem.id!);
                        // Update persisted sessions flag after restoration
                        this.checkPersistedSessions();
                    } catch (error) {
                        this.logger.error('Failed to restore chat session', error);
                        this.messageService.error(nls.localize('theia/ai/chat-ui/failedToRestoreSession', 'Failed to restore chat session'));
                        defer.resolve(undefined);
                        quickPick.hide();
                        return;
                    }
                }
            }
            defer.resolve(selectedItem);
            quickPick.hide();
        });

        quickPick.onDidHide(() => defer.resolve(undefined));

        return defer.promise;
    }

    protected async renameSession(sessionId: string): Promise<void> {
        const name = await this.quickInputService.input({
            placeHolder: nls.localize('theia/ai/chat-ui/enterChatName', 'Enter chat name')
        });
        if (name && name.length > 0) {
            await this.chatService.renameSession(sessionId, name);
        }
    }

    protected async deleteSession(sessionId: string, confirm = false): Promise<void> {
        if (confirm) {
            const confirmed = await new ConfirmDialog({
                title: nls.localize('theia/ai/chat-ui/deleteChat', 'Delete Chat'),
                msg: nls.localize('theia/ai/chat-ui/confirmDeleteChatMsg', 'Are you sure you want to delete this chat?')
            }).open();
            if (!confirmed) {
                return;
            }
        }
        const activeSession = this.chatService.getActiveSession();
        try {
            await this.chatService.deleteSession(sessionId);
            this.checkPersistedSessions();
            if (activeSession && activeSession.id === sessionId) {
                this.chatService.createSession(ChatAgentLocation.Panel, { focus: true });
            }
        } catch (error) {
            this.logger.error('Failed to delete chat session', error);
            this.messageService.error(
                nls.localize('theia/ai/chat-ui/failedToDeleteSession', 'Failed to delete chat session')
            );
        }
    }

    protected withWidget(
        widget: Widget | undefined = this.tryGetWidget(),
        predicate: (output: ChatViewWidget) => boolean = () => true
    ): boolean | false {
        return widget instanceof ChatViewWidget ? predicate(widget) : false;
    }

    protected extractChatView(chatView: ChatViewWidget): void {
        this.secondaryWindowHandler.moveWidgetToSecondaryWindow(chatView);
    }

    canExtractChatView(chatView: ChatViewWidget): boolean {
        return !chatView.secondaryWindow;
    }

    protected async summarizeActiveSession(): Promise<string | undefined> {
        const activeSession = this.chatService.getActiveSession();
        if (!activeSession) { return; }
        return this.taskContextService.summarize(activeSession).catch(err => {
            console.warn('Error while summarizing session:', err);
            this.messageService.error(nls.localize('theia/ai/chat-ui/unableToSummarizeCurrentSession',
                'Unable to summarize current session. Please confirm that the summary agent is not disabled.'));
            return undefined;
        });
    }

    /**
     * Prompts the user to select a chat agent
     * @returns The selected agent or undefined if cancelled
     */
    /**
     * Prompts the user to select a chat agent with an optional default (pre-selected) agent.
     * @param defaultAgentId The id of the agent to pre-select, if present
     * @returns The selected agent or undefined if cancelled
     */
    protected async selectAgent(defaultAgentId?: string): Promise<ChatAgent | undefined> {
        const agents = this.chatAgentService.getAgents();
        if (agents.length === 0) {
            this.messageService.warn(nls.localize('theia/ai/chat-ui/noChatAgentsAvailable', 'No chat agents available.'));
            return undefined;
        }

        const items: QuickPickItem[] = agents.map(agent => ({
            label: agent.name || agent.id,
            description: agent.description,
            id: agent.id
        }));

        let preselected: QuickPickItem | undefined = undefined;
        if (defaultAgentId) {
            preselected = items.find(item => item.id === defaultAgentId);
        }

        const selected = await this.quickInputService.showQuickPick(items, {
            placeholder: nls.localize('theia/ai/chat-ui/selectAgentQuickPickPlaceholder', 'Select an agent for the new session'),
            activeItem: preselected
        });

        if (!selected) {
            return undefined;
        }

        return this.chatAgentService.getAgent(selected.id!);
    }

    /**
     * Prompts the user to select a task context with special marking for currently opened files
     * @returns The selected task context ID or undefined if cancelled
     */
    protected async selectTaskContextWithMarking(): Promise<string | undefined> {
        const contexts = this.taskContextService.getAll();
        const openedFilesInfo = this.getOpenedTaskContextFiles();

        // Create items with opened files marked and prioritized
        const items: QuickPickItem[] = contexts.map(summary => {
            const isOpened = openedFilesInfo.openedIds.includes(summary.id);
            const isActive = openedFilesInfo.activeId === summary.id;
            return {
                label: isOpened ? `📄 ${summary.label} (${nls.localize('theia/ai/chat-ui/selectTaskContextQuickPickItem/currentlyOpen', 'currently open')})` : summary.label,
                description: summary.id,
                id: summary.id,
                // We'll sort active file first, then opened files, then others
                sortText: isActive ? `0-${summary.label}` : isOpened ? `1-${summary.label}` : `2-${summary.label}`
            };
        }).sort((a, b) => a.sortText!.localeCompare(b.sortText!));

        const selected = await this.quickInputService.showQuickPick(items, {
            placeholder: nls.localize('theia/ai/chat-ui/selectTaskContextQuickPickPlaceholder', 'Select a task context to attach')
        });

        return selected?.id;
    }

    /**
     * Returns information about task context files that are currently opened
     * @returns Object with arrays of opened context IDs and the active context ID
     */
    protected getOpenedTaskContextFiles(): { openedIds: string[], activeId?: string } {
        // Get all contexts with their URIs
        const allContexts = this.taskContextService.getAll();
        const contextMap = new Map<string, string>(); // Map of URI -> ID
        // Create a map of URI string -> context ID for lookup
        for (const context of allContexts) {
            if (context.uri) {
                contextMap.set(context.uri.toString(), context.id);
            }
        }

        // Get all open editor URIs
        const openEditorUris = this.editorManager.all.map(widget => widget.editor.uri.toString());

        // Get the currently active/focused editor URI if any
        const activeEditorUri = this.editorManager.currentEditor?.editor.uri.toString();
        let activeContextId: string | undefined;

        if (activeEditorUri) {
            activeContextId = contextMap.get(activeEditorUri);
        }

        // Filter to only task context files that are currently opened
        const openedContextIds: string[] = [];
        for (const uri of openEditorUris) {
            const contextId = contextMap.get(uri);
            if (contextId) {
                openedContextIds.push(contextId);
            }
        }

        return { openedIds: openedContextIds, activeId: activeContextId };
    }
}

import { error } from '@vltpkg/error-cause'
import { randomBytes } from 'node:crypto'
import { lstat, mkdir, rename, writeFile } from 'node:fs/promises'
import { basename, dirname, parse, resolve } from 'node:path'
import { rimraf } from 'rimraf'
import { Header } from 'tar/header'
import type { HeaderData } from 'tar/header'
import { Pax } from 'tar/pax'
import { unzip as unzipCB } from 'node:zlib'
import { findTarDir } from './find-tar-dir.ts'

const unzip = async (input: Buffer) =>
  new Promise<Buffer>(
    (res, rej) =>
      /* c8 ignore start */
      unzipCB(input, (er, result) => (er ? rej(er) : res(result))),
    /* c8 ignore stop */
  )

const exists = async (path: string): Promise<boolean> => {
  try {
    await lstat(path)
    return true
  } catch {
    return false
  }
}

let id = 1
const tmp = randomBytes(6).toString('hex') + '.'
const tmpSuffix = () => tmp + String(id++)

const checkFs = (
  h: Header,
  tarDir: string | undefined,
): h is Header & { path: string } => {
  /* c8 ignore start - impossible */
  if (!h.path) return false
  if (!tarDir) return false
  /* c8 ignore stop */
  h.path = h.path.replace(/[\\/]+/g, '/')
  const parsed = parse(h.path)
  if (parsed.root) return false
  const p = h.path.replace(/\\/, '/')
  // any .. at the beginning, end, or middle = no good
  if (/(\/|)^\.\.(\/|$)/.test(p)) return false
  // packages should always be in a 'package' tarDir in the archive
  if (!p.startsWith(tarDir)) return false
  return true
}

const write = async (
  path: string,
  body: Buffer,
  executable = false,
) => {
  await mkdirp(dirname(path))
  // if the mode is world-executable, then make it executable
  // this is needed for some packages that have a file that is
  // not a declared bin, but still used as a cli executable.
  await writeFile(path, body, {
    mode: executable ? 0o777 : 0o666,
  })
}

const made = new Set<string>()
const making = new Map<string, Promise<boolean>>()
const mkdirp = async (d: string) => {
  if (!made.has(d)) {
    const m =
      making.get(d) ??
      mkdir(d, { recursive: true, mode: 0o777 }).then(() =>
        making.delete(d),
      )
    making.set(d, m)
    await m
    made.add(d)
  }
}

export const unpack = async (
  tarData: Buffer,
  target: string,
): Promise<void> => {
  const isGzip = tarData[0] === 0x1f && tarData[1] === 0x8b
  await unpackUnzipped(
    isGzip ? await unzip(tarData) : tarData,
    target,
  )
}

const unpackUnzipped = async (
  buffer: Buffer,
  target: string,
): Promise<void> => {
  /* c8 ignore start */
  const isGzip = buffer[0] === 0x1f && buffer[1] === 0x8b
  if (isGzip) {
    throw error('still gzipped after unzipping', {
      found: isGzip,
      wanted: false,
    })
  }
  /* c8 ignore stop */

  // another real quick gutcheck before we get started
  if (buffer.length % 512 !== 0) {
    throw error('Invalid tarball: length not divisible by 512', {
      found: buffer.length,
    })
  }
  if (buffer.length < 1024) {
    throw error(
      'Invalid tarball: not terminated by 1024 null bytes',
      { found: buffer.length },
    )
  }
  // make sure the last kb is all zeros
  for (let i = buffer.length - 1024; i < buffer.length; i++) {
    if (buffer[i] !== 0) {
      throw error(
        'Invalid tarball: not terminated by 1024 null bytes',
        { found: buffer.subarray(i, i + 10) },
      )
    }
  }

  const tmp =
    dirname(target) + '/.' + basename(target) + '.' + tmpSuffix()
  const og = tmp + '.ORIGINAL'
  await Promise.all([rimraf(tmp), rimraf(og)])

  let succeeded = false
  try {
    let tarDir: string | undefined = undefined
    let offset = 0
    let h: Header
    let ex: HeaderData | undefined = undefined
    let gex: HeaderData | undefined = undefined
    while (
      offset < buffer.length &&
      !(h = new Header(buffer, offset, ex, gex)).nullBlock
    ) {
      offset += 512
      ex = undefined
      gex = undefined
      const size = h.size ?? 0
      const body = buffer.subarray(offset, offset + size)
      // skip invalid headers
      if (!h.cksumValid) continue
      offset += 512 * Math.ceil(size / 512)

      // TODO: tarDir might not be named "package/"
      // find the first tarDir in the first entry, and use that.
      switch (h.type) {
        case 'File':
          if (!tarDir) tarDir = findTarDir(h.path, tarDir)
          /* c8 ignore next */
          if (!tarDir) continue
          if (!checkFs(h, tarDir)) continue
          await write(
            resolve(tmp, h.path.substring(tarDir.length)),
            body,
            // if it's world-executable, it's an executable
            // otherwise, make it read-only.
            1 === ((h.mode ?? 0x666) & 1),
          )
          break

        case 'Directory':
          /* c8 ignore next 2 */
          if (!tarDir) tarDir = findTarDir(h.path, tarDir)
          if (!tarDir) continue
          if (!checkFs(h, tarDir)) continue
          await mkdirp(resolve(tmp, h.path.substring(tarDir.length)))
          break

        case 'GlobalExtendedHeader':
          gex = Pax.parse(body.toString(), gex, true)
          break

        case 'ExtendedHeader':
        case 'OldExtendedHeader':
          ex = Pax.parse(body.toString(), ex, false)
          break

        case 'NextFileHasLongPath':
        case 'OldGnuLongPath':
          ex ??= Object.create(null) as HeaderData
          ex.path = body.toString().replace(/\0.*/, '')
          break
      }
    }

    const targetExists = await exists(target)
    if (targetExists) await rename(target, og)
    await rename(tmp, target)
    if (targetExists) await rimraf(og)
    succeeded = true
  } finally {
    // do not handle error or obscure throw site, just do the cleanup
    // if it didn't complete successfully.
    if (!succeeded) {
      /* c8 ignore start */
      if (await exists(og)) {
        await rimraf(target)
        await rename(og, target)
      }
      /* c8 ignore stop */
      await rimraf(tmp)
    }
  }
}

//! Portable "best effort" implementation of `Cmov`.
//!
//! This implementation is based on portable bitwise arithmetic but cannot
//! guarantee that the resulting generated assembly is free of branch
//! instructions.

// TODO(tarcieri): more optimized implementation for small integers

use crate::{Cmov, CmovEq, Condition};
use core::hint::black_box;

/// Bitwise non-zero: returns `1` if `x != 0`, and otherwise returns `0`.
macro_rules! bitnz {
    ($value:expr, $bits:expr) => {
        ($value | $value.wrapping_neg()) >> ($bits - 1)
    };
}

impl Cmov for u16 {
    #[inline]
    fn cmovnz(&mut self, value: &Self, condition: Condition) {
        let mut tmp = *self as u64;
        tmp.cmovnz(&(*value as u64), condition);
        *self = tmp as u16;
    }

    #[inline]
    fn cmovz(&mut self, value: &Self, condition: Condition) {
        let mut tmp = *self as u64;
        tmp.cmovz(&(*value as u64), condition);
        *self = tmp as u16;
    }
}

impl CmovEq for u16 {
    #[inline]
    fn cmovne(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        (*self as u64).cmovne(&(*rhs as u64), input, output);
    }

    #[inline]
    fn cmoveq(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        (*self as u64).cmoveq(&(*rhs as u64), input, output);
    }
}

impl Cmov for u32 {
    #[inline]
    fn cmovnz(&mut self, value: &Self, condition: Condition) {
        let mut tmp = *self as u64;
        tmp.cmovnz(&(*value as u64), condition);
        *self = tmp as u32;
    }

    #[inline]
    fn cmovz(&mut self, value: &Self, condition: Condition) {
        let mut tmp = *self as u64;
        tmp.cmovz(&(*value as u64), condition);
        *self = tmp as u32;
    }
}

impl CmovEq for u32 {
    #[inline]
    fn cmovne(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        (*self as u64).cmovne(&(*rhs as u64), input, output);
    }

    #[inline]
    fn cmoveq(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        (*self as u64).cmoveq(&(*rhs as u64), input, output);
    }
}

impl Cmov for u64 {
    #[inline]
    fn cmovnz(&mut self, value: &Self, condition: Condition) {
        let mask = black_box((bitnz!(condition, u8::BITS) as u64).wrapping_sub(1));
        *self = (*self & mask) | (*value & !mask);
    }

    #[inline]
    fn cmovz(&mut self, value: &Self, condition: Condition) {
        let mask = black_box((1 ^ bitnz!(condition, u8::BITS) as u64).wrapping_sub(1));
        *self = (*self & mask) | (*value & !mask);
    }
}

impl CmovEq for u64 {
    #[inline]
    fn cmovne(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        let ne = bitnz!(self ^ rhs, u64::BITS) as u8;
        output.cmovnz(&input, black_box(ne));
    }

    #[inline]
    fn cmoveq(&self, rhs: &Self, input: Condition, output: &mut Condition) {
        let ne = bitnz!(self ^ rhs, u64::BITS) as u8;
        output.cmovnz(&input, black_box(ne ^ 1));
    }
}

import type { UpgradeWebSocket, WSContext } from 'hono/ws'
import { defineWebSocketHelper } from 'hono/ws'
import type { IncomingMessage } from 'node:http'
import { STATUS_CODES } from 'node:http'
import type { Duplex } from 'node:stream'
import type { FetchCallback, ServerType } from './types'
import type { WebSocketData, WebSocketLike, WebSocketServerLike } from './websocket-types'

interface CloseEventInit extends EventInit {
  code?: number
  reason?: string
  wasClean?: boolean
}

/**
 * @link https://developer.mozilla.org/en-US/docs/Web/API/CloseEvent
 */
export const CloseEvent: typeof globalThis.CloseEvent =
  globalThis.CloseEvent ??
  class extends Event {
    #eventInitDict

    constructor(type: string, eventInitDict: CloseEventInit = {}) {
      super(type, eventInitDict)
      this.#eventInitDict = eventInitDict
    }

    get wasClean(): boolean {
      return this.#eventInitDict.wasClean ?? false
    }

    get code(): number {
      return this.#eventInitDict.code ?? 0
    }

    get reason(): string {
      return this.#eventInitDict.reason ?? ''
    }
  }

interface ErrorEventInit extends EventInit {
  message?: string
  filename?: string
  lineno?: number
  colno?: number
  error?: unknown
}

/**
 * Node.js has no global `ErrorEvent`, unlike `Event`/`MessageEvent`/`CloseEvent`.
 * @link https://developer.mozilla.org/en-US/docs/Web/API/ErrorEvent
 */
export const ErrorEvent: typeof globalThis.ErrorEvent =
  globalThis.ErrorEvent ??
  class extends Event {
    #eventInitDict

    constructor(type: string, eventInitDict: ErrorEventInit = {}) {
      super(type, eventInitDict)
      this.#eventInitDict = eventInitDict
    }

    get message(): string {
      return this.#eventInitDict.message ?? ''
    }

    get filename(): string {
      return this.#eventInitDict.filename ?? ''
    }

    get lineno(): number {
      return this.#eventInitDict.lineno ?? 0
    }

    get colno(): number {
      return this.#eventInitDict.colno ?? 0
    }

    get error(): unknown {
      return this.#eventInitDict.error ?? null
    }
  }

const generateConnectionSymbol = () => Symbol('connection')

type WaitForWebSocket = (
  request: IncomingMessage,
  connectionSymbol: symbol
) => Promise<WebSocketLike>

const CONNECTION_SYMBOL_KEY: unique symbol = Symbol('CONNECTION_SYMBOL_KEY')
const WAIT_FOR_WEBSOCKET_SYMBOL: unique symbol = Symbol('WAIT_FOR_WEBSOCKET_SYMBOL')

export type UpgradeBindings = {
  incoming: IncomingMessage
  outgoing: undefined
  wss: WebSocketServerLike
  [CONNECTION_SYMBOL_KEY]?: symbol
  [WAIT_FOR_WEBSOCKET_SYMBOL]?: WaitForWebSocket
}

type UpgradeWebSocketOptions = {
  onError: (err: unknown) => void
}

// Hop-by-hop headers per RFC 9110 Section 7.6.1
// (https://www.rfc-editor.org/rfc/rfc9110.html#name-connection) plus
// `keep-alive` (commonly treated as hop-by-hop by HTTP implementations) and
// WebSocket handshake headers managed by `ws` itself. These must not be
// forwarded onto the upgrade response or the handshake will be corrupted.
const responseHeadersToSkip = new Set([
  'connection',
  'content-length',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailer',
  'transfer-encoding',
  'upgrade',
  'sec-websocket-accept',
  'sec-websocket-extensions',
  'sec-websocket-protocol',
])

const appendResponseHeaders = (headers: string[], responseHeaders?: Headers) => {
  if (!responseHeaders) {
    return
  }
  responseHeaders.forEach((value, key) => {
    if (responseHeadersToSkip.has(key.toLowerCase())) {
      return
    }
    headers.push(`${key}: ${value}`)
  })
}

const rejectUpgradeRequest = (socket: Duplex, status: number, responseHeaders?: Headers) => {
  const responseLines = ['Connection: close', 'Content-Length: 0']
  appendResponseHeaders(responseLines, responseHeaders)

  socket.end(
    `HTTP/1.1 ${status.toString()} ${STATUS_CODES[status] ?? ''}\r\n` +
      `${responseLines.join('\r\n')}\r\n` +
      '\r\n'
  )
}

const createUpgradeRequest = (request: IncomingMessage): Request => {
  const protocol = (request.socket as { encrypted?: boolean }).encrypted ? 'https' : 'http'
  const url = new URL(request.url ?? '/', `${protocol}://${request.headers.host ?? 'localhost'}`)
  const headers = new Headers()
  for (const key in request.headers) {
    const value = request.headers[key]
    if (!value) {
      continue
    }
    headers.append(key, Array.isArray(value) ? value[0] : value)
  }
  return new Request(url, {
    headers,
  })
}

export const setupWebSocket = (options: {
  server: ServerType
  fetchCallback: FetchCallback
  wss: WebSocketServerLike
}): void => {
  const { server, fetchCallback, wss } = options

  const waiterMap = new Map<
    IncomingMessage,
    { resolve: (ws: WebSocketLike) => void; connectionSymbol: symbol }
  >()

  wss.on('connection', (ws, request) => {
    const waiter = waiterMap.get(request)
    if (waiter) {
      waiter.resolve(ws)
      waiterMap.delete(request)
    }
  })

  const waitForWebSocket: WaitForWebSocket = (request, connectionSymbol) => {
    return new Promise<WebSocketLike>((resolve) => {
      waiterMap.set(request, { resolve, connectionSymbol })
    })
  }

  server.on('upgrade', async (request, socket: Duplex, head) => {
    if (request.headers.upgrade?.toLowerCase() !== 'websocket') {
      return
    }

    const env: UpgradeBindings = {
      incoming: request,
      outgoing: undefined,
      wss,
      [WAIT_FOR_WEBSOCKET_SYMBOL]: waitForWebSocket,
    }

    let status = 400
    let responseHeaders: Headers | undefined
    try {
      const response = (await fetchCallback(
        createUpgradeRequest(request),
        env as unknown as Parameters<FetchCallback>[1]
      )) as Response
      if (response instanceof Response) {
        status = response.status
        responseHeaders = response.headers
      }
    } catch {
      if (server.listenerCount('upgrade') === 1) {
        rejectUpgradeRequest(socket, 500)
      }
      return
    }

    const waiter = waiterMap.get(request)

    if (!waiter || waiter.connectionSymbol !== env[CONNECTION_SYMBOL_KEY]) {
      waiterMap.delete(request)
      if (server.listenerCount('upgrade') === 1) {
        rejectUpgradeRequest(socket, status, responseHeaders)
      }
      return
    }

    const addResponseHeaders = (headers: string[]) => {
      appendResponseHeaders(headers, responseHeaders)
    }

    // `headers` is emitted synchronously inside `handleUpgrade`, so this
    // listener cannot leak across concurrent upgrades on the shared `wss`.
    wss.on('headers', addResponseHeaders)
    try {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit('connection', ws, request)
      })
    } finally {
      wss.off('headers', addResponseHeaders)
    }
  })

  server.on('close', () => {
    wss.close()
  })
}

export const upgradeWebSocket: UpgradeWebSocket<WebSocketLike, UpgradeWebSocketOptions> =
  defineWebSocketHelper(async (c, events, options) => {
    if (c.req.header('upgrade')?.toLowerCase() !== 'websocket') {
      return
    }

    const env = c.env as UpgradeBindings
    const waitForWebSocket = env[WAIT_FOR_WEBSOCKET_SYMBOL]

    if (!waitForWebSocket || !env.incoming) {
      return new Response(null, { status: 500 })
    }

    const connectionSymbol = generateConnectionSymbol()
    env[CONNECTION_SYMBOL_KEY] = connectionSymbol
    ;(async () => {
      const ws = await waitForWebSocket(env.incoming, connectionSymbol)

      const messagesReceivedInStarting: [data: WebSocketData, isBinary: boolean][] = []
      const bufferMessage = (data: WebSocketData, isBinary: boolean) => {
        messagesReceivedInStarting.push([data, isBinary])
      }
      ws.on('message', bufferMessage)

      const ctx: WSContext<WebSocketLike> = {
        binaryType: 'arraybuffer',
        close(code, reason) {
          ws.close(code, reason)
        },
        protocol: ws.protocol,
        raw: ws,
        get readyState() {
          return ws.readyState
        },
        send(source, opts) {
          ws.send(source, {
            compress: opts?.compress,
          })
        },
        url: new URL(c.req.url),
      }

      try {
        events?.onOpen?.(new Event('open'), ctx)
      } catch (e) {
        ;(options?.onError ?? console.error)(e)
      }

      const handleMessage = (data: WebSocketData, isBinary: boolean) => {
        const datas = Array.isArray(data) ? data : [data]
        for (const data of datas) {
          try {
            events?.onMessage?.(
              new MessageEvent('message', {
                data: isBinary
                  ? data instanceof ArrayBuffer
                    ? data
                    : data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength)
                  : typeof data === 'string'
                    ? data
                    : Buffer.from(data).toString('utf-8'),
              }),
              ctx
            )
          } catch (e) {
            ;(options?.onError ?? console.error)(e)
          }
        }
      }

      ws.off('message', bufferMessage)
      for (const message of messagesReceivedInStarting) {
        handleMessage(...message)
      }

      ws.on('message', (data, isBinary) => {
        handleMessage(data, isBinary)
      })

      ws.on('close', (code, reason) => {
        try {
          events?.onClose?.(new CloseEvent('close', { code, reason: reason.toString() }), ctx)
        } catch (e) {
          ;(options?.onError ?? console.error)(e)
        }
      })

      ws.on('error', (error) => {
        try {
          events?.onError?.(
            new ErrorEvent('error', {
              error,
            }),
            ctx
          )
        } catch (e) {
          ;(options?.onError ?? console.error)(e)
        }
      })
    })()

    return new Response()
  })

