	return &authModel.GoogleTokenResponse{
		AccessToken:  token.AccessToken,
		TokenType:    token.TokenType,
		ExpiresIn:    expiresIn,
		RefreshToken: token.RefreshToken,
		Scope:        fmt.Sprint(token.Extra("scope")),
		IDToken:      fmt.Sprint(token.Extra("id_token")),
	}, nil
}

